describe('Out of Stock Message on Add to Cart', () => {
  beforeEach(() => {
    cy.visit('/products/unavailable-item');
  });

  it('should display out of stock message when adding unavailable item to cart', () => {
    // Verify product page loads
    cy.get('[data-testid="product-name"]').should('contain', 'Unavailable Item');
    cy.get('[data-testid="price"]').should('be.visible');

    // Attempt to add to cart
    cy.get('[data-testid="add-to-cart-button"]').click();

    // Verify out of stock message appears
    cy.get('[data-testid="out-of-stock-message"]')
      .should('be.visible')
      .should('contain', 'Out of Stock');

    // Verify error styling is applied
    cy.get('[data-testid="out-of-stock-message"]')
      .should('have.class', 'error-text');

    // Verify cart icon does not update
    cy.get('[data-testid="cart-count"]').should('contain', '0');

    // Verify user is not redirected
    cy.url().should('include', '/products/unavailable-item');
  });

  it('should handle multiple attempts to add out of stock item', () => {
    // First attempt
    cy.get('[data-testid="add-to-cart-button"]').click();
    cy.get('[data-testid="out-of-stock-message"]')
      .should('be.visible')
      .should('contain', 'Out of Stock');

    // Second attempt
    cy.get('[data-testid="add-to-cart-button"]').click();
    cy.get('[data-testid="out-of-stock-message"]')
      .should('be.visible')
      .should('contain', 'Out of Stock');

    // Verify message persists and does not change
    cy.get('[data-testid="out-of-stock-message"]')
      .should('have.text', 'This item is currently out of stock');

    // Verify cart count remains 0
    cy.get('[data-testid="cart-count"]').should('contain', '0');

    // Verify disabled state of button after multiple attempts
    cy.get('[data-testid="add-to-cart-button"]')
      .should('be.disabled');
  });
});
